// import type { ComponentStyleVariantConfig, Theme } from "@types";
import type { ChipBarProps } from "./chip-bar.types";
import type { CSSObject } from "@emotion/react";

import { ChipClasses } from "@components/chip/chip.styles";
import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "ChipBar";

// Generate child element class names for the component, should match available style slots
export const ChipBarClasses = {
  root: "exp-textura_chip-bar",
  chipWrapper: "exp-textura_chip-bar_chip_wrapper",
  chipWrapperSelected: "exp-textura_chip-bar_chip_wrapper_selected",
  chipWrapperSelectable: "exp-textura_chip-bar_chip_wrapper_selectable",
  overflowContent: "exp-textura_chip-bar_overflow_content",
};

// Set up style variant settings for the component (if more than "default"), using style slots
// const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
//   exampleVariant: { root: { backgroundColor: theme.color.background.default } },
// });

const generateStyles = (props: ChipBarProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<ChipBarProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        // getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    display: "flex",
    width: "100%",
    alignItems: "center",
    gap: theme.toRem(theme.spacing[8]),

    [`& .${ChipBarClasses.chipWrapper}`]: {
      display: "inline-flex",
      cursor: "pointer",
      borderRadius: theme.toRem(theme.border.radius.lg),
      ...styleSlots?.chipWrapper,
    },

    [`& .${ChipBarClasses.chipWrapperSelectable}`]: {
      cursor: "pointer",
      ...styleSlots?.chipSelectable,
      ...styleSlots?.chipWrapperSelectable,
    },

    [`& .${ChipBarClasses.chipWrapperSelected}`]: {
      backgroundColor: theme.color.background.actionSelected,
      borderColor: theme.color.transparency.transparent,
      color: theme.color.content.strong,
      paddingInlineStart: theme.toRem(theme.spacing[8]),
      [`&.${ChipClasses.outline}`]: {
        backgroundColor: theme.color.background.actionSelected,
        border: "none",
        ...styleSlots?.chipSelected,
      },
      ...styleSlots?.chipSelected,
      ...styleSlots?.chipWrapperSelected,
    },

    [`.${ChipBarClasses.overflowContent}`]: {
      display: "flex",
      flexDirection: "row",
      flexWrap: "wrap",
      gap: theme.toRem(theme.spacing[8]),
      ...styleSlots?.overflowContent,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledChipBar = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<ChipBarProps>((props) => generateStyles(props));
